-- Consulta: Gerar Ocorrencias Mensais no Movto
-- Tipo: Acréscimo (64)
-- Parâmetros: [Forms]![F Gerar Ocorrencias Mensais]![AnoOcorrencia] (Texto), [Forms]![F Gerar Ocorrencias Mensais]![ProximoMes] (Texto), Formulários![F Gerar Ocorrencias Mensais]!AnoOcorrencia (Texto), Formulários![F Gerar Ocorrencias Mensais]!ProximoMes (Texto)
-- Descrição: 

INSERT INTO [F Movimento Contas] ( DataVencto, EmitirCheque, AnoOcorrenciaMensal, MesOcorrenciaMensal, Plano2, Plano1, EmpVinculada, CodigoParceiro, CodHistorico, DataMovto, ValorDebito, ValorCredito, Complemento, Plano3, ContaFinanceira, Integracao, Observacao, NumDoc, PagamentoLote )
SELECT DateSerial([Forms]![F Gerar Ocorrencias Mensais]![AnoOcorrencia],[Forms]![F Gerar Ocorrencias Mensais]![ProximoMes],[Ocorrencias Mensais]![DiaVencimento]) AS Expr1, [Ocorrencias Mensais].EmitirCheque, Formulários![F Gerar Ocorrencias Mensais]!AnoOcorrencia AS AnoOcorrencia, Formulários![F Gerar Ocorrencias Mensais]!ProximoMes AS MesOcorrencia, Plano2.Plano2, Plano1.Plano1, [Ocorrencias Mensais].EmpVinculada, [Ocorrencias Mensais].CodigoParceiro, [Ocorrencias Mensais].CodHistorico, DateSerial([Forms]![F Gerar Ocorrencias Mensais]![AnoOcorrencia],[Forms]![F Gerar Ocorrencias Mensais]![ProximoMes],[Ocorrencias Mensais]![DiaVencimento]) AS DTMov, [Ocorrencias Mensais].ValorDebito, [Ocorrencias Mensais].ValorCredito, [Ocorrencias Mensais].Complemento, [Ocorrencias Mensais].Plano3, [Ocorrencias Mensais].ContaFinanceira, [Ocorrencias Mensais].Integracao, "[OM] " & [Observacao] AS Obs, [Ocorrencias Mensais].NumDoc, [Ocorrencias Mensais].PagamentoLote
FROM (Plano1 INNER JOIN Plano2 ON Plano1.Plano1=Plano2.Plano1) INNER JOIN ([Ocorrencias Mensais] INNER JOIN Plano3 ON [Ocorrencias Mensais].Plano3=Plano3.Plano3) ON Plano2.Plano2=Plano3.Plano2;
